#include <iostream>
#include <memory>
#include <string>

class Data { public: Data(std::string name) : name_(name) { std::cout << "Data '" << name_ << "' created.\n"; } ~Data() { std::cout << "Data '" << name_ << "' destroyed.\n"; } private: std::string name_; };

int main() {
    std::shared_ptr<Data> sp_main;

    {
        // 1. Creation from raw pointer: allocates Data, then allocates a control block.
        std::cout << "Creating initial shared_ptr from raw pointer.\n";
        auto* raw_ptr = new Data("MyData");
        std::shared_ptr<Data> sp1(raw_ptr);
        std::cout << "sp1 use_count: " << sp1.use_count() << std::endl; // is 1

        // 2. Copy construction: cheap. Copies pointers and increments ref count.
        // No new control block is allocated.
        std::cout << "\nCreating sp2 by copying sp1.\n";
        auto sp2 = sp1;
        std::cout << "sp1 use_count: " << sp1.use_count() << std::endl; // is 2
        std::cout << "sp2 use_count: " << sp2.use_count() << std::endl; // is 2

        // 3. Weak pointer: increments weak count, not strong count.
        std::weak_ptr<Data> wp = sp1;
        std::cout << "\nCreated weak_ptr. use_count is still: " << sp1.use_count() << std::endl; // still 2

        sp_main = sp1; // Another shared owner
        std::cout << "sp_main now shares ownership. use_count: " << sp_main.use_count() << std::endl; // is 3

        std::cout << "\nLeaving inner scope. sp1 and sp2 will be destroyed.\n";
    }
    // sp1 and sp2 are destroyed, ref count drops to 1.
    std::cout << "\nBack in main scope. sp_main use_count: " << sp_main.use_count() << std::endl; // is 1

    std::cout << "Resetting sp_main.\n";
    sp_main.reset(); // Ref count drops to 0. Data is destroyed. Control block might persist if weak_ptr exists.

    std::cout << "sp_main is now null.\n";
    return 0;
}
